{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A thoughtful cohort approach for transitions</title>
  <meta name="description" content="Therapeutic cohort and individual work for busy adults in {{CITY}}, {{STATE}}. Grounded clinical care with practical tools and confidentiality." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg width="40" height="40" viewBox="0 0 100 100" aria-hidden="true">
        <rect x="10" y="10" width="80" height="80" rx="16" fill="rgba(255,255,255,0.06)" />
        <circle cx="50" cy="40" r="10" fill="rgba(255,255,255,0.12)" />
        <rect x="35" y="56" width="30" height="10" rx="3" fill="rgba(255,255,255,0.09)" />
      </svg>
      <div class="brand-text">
        <strong>{{BUSINESS_NAME}}</strong>
        <small>{{TAGLINE}}</small>
      </div>
    </div>
    <nav class="main-nav">
      <a href="index.html">Home</a>
      <a href="about.html">Why Work Together</a>
      <a href="specialties.html">Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Investment</a>
      <a href="faq.html">Questions</a>
      <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html" class="muted">Reach</a>
    </nav>
  </header>

  <main class="layout">
    <!-- Hero -->
    <section class="hero glass">
      <div class="hero-inner">
        <h1>Practical clinical support for real-life transitions</h1>
        <p class="lead">I run small cohorts and individual sessions focused on skills you can actually use between meetings — structured, confidential, and clinician-led.</p>
        <div class="hero-actions">
          <a href="book.html" class="btn primary">Join a cohort — next start dates inside</a>
          <a href="contact.html" class="btn ghost">Ask a question</a>
        </div>
        <div class="hero-meta">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
      <svg class="hero-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern-1"></use></svg>
    </section>

    <!-- Benefits (placed early for different order) -->
    <section class="benefits glass" id="benefits">
      <h2>What you can expect</h2>
      <p class="muted">My work blends evidence-based approaches with real-world pacing — we aim for reliable change you can maintain.</p>
      <ul class="benefit-list">
        <li>
          <strong>Coaching-shaped cohorts</strong>
          <p>Time-limited group cohorts that practice skills together and keep momentum between sessions.</p>
        </li>
        <li>
          <strong>Focused individual sessions</strong>
          <p>Short-term work for clarity and tools, or longer clinical partnerships as needed.</p>
        </li>
        <li>
          <strong>Clear boundaries & confidentiality</strong>
          <p>Clinical notes, privacy, and scope are explained at intake. If you are in crisis, call local emergency services or crisis lines immediately.</p>
        </li>
      </ul>
    </section>

    <!-- Social proof -->
    <section class="social-proof glass" id="social-proof">
      <h2>People say it feels different</h2>
      <div class="testimonials">
        <blockquote>
          "I joined the Cohort Lab and left with practices I still use. Warm, practical, and realistic."<cite>— A. from {{CITY}}</cite>
        </blockquote>
        <blockquote>
          "Short sessions that cut through overwhelm and helped me make steady adjustments."<cite>— J. in {{STATE}}</cite>
        </blockquote>
      </div>
    </section>

    <!-- Process -->
    <section class="process glass" id="process">
      <h2>How this typically works</h2>
      <ol>
        <li><strong>Intake & orientation</strong> — brief intake to match needs and cohort timing.</li>
        <li><strong>Choose a path</strong> — cohort, focused sessions, or a short package.</li>
        <li><strong>Group meets & practices</strong> — structured weekly touchpoints and between-session tasks.</li>
        <li><strong>Wrap & next steps</strong> — review what stuck and plan follow-up care if helpful.</li>
      </ol>
    </section>

    <!-- Pricing + interactive comparator -->
    <section class="pricing glass" id="pricing">
      <h2>Investment — choose what fits</h2>
      <p class="muted">Toggle between monthly pricing and package pricing. Numbers animate so you can compare quickly.</p>

      <div class="toggle-row">
        <label class="switch">
          <input id="priceToggle" type="checkbox" aria-label="Toggle pricing view" />
          <span class="slider"></span>
        </label>
        <div class="toggle-labels"><span>Monthly</span><span>Package</span></div>
      </div>

      <div class="pricing-grid">
        <div class="price-card">
          <h3>Cohort Lab — 8 weeks</h3>
          <div class="price"><span class="price-value" data-monthly="180" data-package="1200">$180</span><small class="price-unit">/month</small></div>
          <p>Group learning with weekly practice and clinician guidance.</p>
          <a href="book.html" class="btn small">Join the cohort</a>
        </div>

        <div class="price-card highlight">
          <h3>Focused Sessions</h3>
          <div class="price"><span class="price-value" data-monthly="140" data-package="800">$140</span><small class="price-unit">/session</small></div>
          <p>Single sessions or limited series tailored to your needs.</p>
          <a href="book.html" class="btn small">Book a session</a>
        </div>

        <div class="price-card">
          <h3>Turnaround Pack — 6</h3>
          <div class="price"><span class="price-value" data-monthly="--" data-package="650">$650</span><small class="price-unit">/pack</small></div>
          <p>Six-session bundle for focused short-term work at a reduced rate.</p>
          <a href="book.html" class="btn small">Reserve a pack</a>
        </div>
      </div>
    </section>

    <!-- Mood-to-Method selector (interactive) -->
    <section class="mood-method glass" id="mood-method">
      <h2>Tell me how you're feeling right now</h2>
      <p class="muted">Choose a state and the page will highlight an approach that often helps clinicians meet those needs.</p>
      <div class="mood-options">
        <button class="mood-btn" data-key="overwhelmed">Overwhelmed</button>
        <button class="mood-btn" data-key="stuck">Stuck</button>
        <button class="mood-btn" data-key="restless">Restless</button>
        <button class="mood-btn" data-key="curious">Curious</button>
      </div>

      <div class="method-card" id="methodCard">
        <h3 id="methodTitle">A measured, practical approach</h3>
        <p id="methodDesc">Choose a mood to see an approach that fits. Clinical scope and confidentiality apply; this is not crisis care.</p>
        <div class="method-actions">
          <a id="methodCta" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a href="contact.html" class="btn ghost">Ask about fit</a>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq glass" id="faq">
      <h2>Frequently asked questions</h2>
      <details>
        <summary>Do you accept insurance?</summary>
        <p class="muted">I offer superbills for out-of-network reimbursement. Insurance acceptance varies; ask at intake.</p>
      </details>
      <details>
        <summary>Is this confidential?</summary>
        <p class="muted">Yes. Clinical records are maintained securely. I will review limits to confidentiality and scope during intake. This site is informational, not a substitute for immediate crisis support.</p>
      </details>
      <details>
        <summary>How do cohorts differ from individual sessions?</summary>
        <p class="muted">Cohorts emphasize shared practice, accountability, and peer learning on a fixed schedule. Individual sessions are tailored and private.</p>
      </details>
    </section>

    <!-- Call to action (closing) -->
    <section class="final-cta glass" id="final-cta">
      <h2>Ready to pick a next step?</h2>
      <p class="muted">Start with a brief intake to figure out if cohort or individual work fits best. No pressure—just a straightforward conversation.</p>
      <div class="cta-row">
        <a href="book.html" class="btn primary large">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html" class="btn ghost">Contact me</a>
      </div>
      <p class="disclaimer">Confidentiality and boundaries explained at intake. If you are in immediate danger or crisis, call local emergency services or a crisis line.</p>
    </section>
  </main>

  <footer class="site-footer">
    <div>
      <small>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Clinician in {{CITY}}, {{STATE}}. Licensed care, not a substitute for emergency services.</small>
    </div>
    <nav class="footer-nav">
      <a href="privacy.html">Privacy</a>
      <a href="terms.html">Terms</a>
      <a href="sitemap.xml">Sitemap</a>
    </nav>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
