{"path":"assets/css/styles.css","content":"/* Glass morphism theme, playful premium voice */
:root{
  --bg:#0f1724;
  --glass: rgba(255,255,255,0.06);
  --glass-2: rgba(255,255,255,0.04);
  --accent:#8be9fd;
  --accent-2:#ffb86b;
  --muted:#cbd5e1;
  --card-radius:14px;
  --max-w:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;padding:0;font-family:Inter, system-ui, sans-serif;background:linear-gradient(180deg,#071126 0%, #0f1724 60%);color:#e6eef6;line-height:1.45;
  background-image:url('assets/img/pattern.svg');background-repeat:repeat; background-size:220px;
}
.layout{max-width:var(--max-w);margin:30px auto;padding:20px}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:14px 22px;backdrop-filter:blur(8px);background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border-radius:12px;margin:18px}
.brand{display:flex;gap:12px;align-items:center}
.brand-text strong{display:block;font-size:1rem}
.brand-text small{display:block;color:var(--muted);font-size:0.8rem}
.main-nav a{color:var(--muted);text-decoration:none;margin-left:14px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#001; padding:8px 12px;border-radius:8px;font-weight:700}
.main-nav a.muted{opacity:0.9;background:transparent;border:1px solid rgba(255,255,255,0.03);padding:6px 10px;border-radius:8px}
.glass{background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.02));border-radius:var(--card-radius);padding:22px;margin:18px 0;box-shadow:0 6px 20px rgba(2,6,23,0.6);backdrop-filter: blur(10px);border:1px solid rgba(255,255,255,0.03)}
.hero{display:flex;align-items:center;justify-content:space-between;position:relative;overflow:hidden}
.hero-inner{max-width:62%}
.hero h1{font-size:2rem;margin:0 0 8px}
.lead{color:var(--muted);margin-bottom:14px}
.hero-actions .btn{margin-right:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;color:#072233;background:rgba(255,255,255,0.06)}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#001}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)}
.btn.small{padding:8px 10px;font-size:0.95rem}
.btn.large{padding:14px 20px;font-size:1.05rem}
.hero-meta{color:var(--muted);font-size:0.9rem;margin-top:10px}
.hero-pattern{position:absolute;right:-20px;bottom:-10px;opacity:0.12;width:320px;height:320px}
.benefits .benefit-list{display:flex;gap:14px;list-style:none;padding:0;margin:12px 0}
.benefit-list li{flex:1}
.social-proof .testimonials{display:flex;gap:12px}
.social-proof blockquote{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:14px;border-radius:10px;border-left:4px solid var(--accent);}
.process ol{padding-left:18px}
.pricing .toggle-row{display:flex;align-items:center;gap:14px;margin-bottom:12px}
.switch{position:relative;display:inline-block;width:58px;height:30px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.25);border-radius:34px;transition:.28s}
.slider:before{position:absolute;content:"";height:22px;width:22px;left:4px;top:4px;background:white;border-radius:50%;transition:.28s}
.switch input:checked + .slider{background:linear-gradient(90deg,var(--accent),var(--accent-2))}
.switch input:checked + .slider:before{transform:translateX(28px)}
.toggle-labels{color:var(--muted);display:flex;gap:18px}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}
.price-card{padding:12px;border-radius:10px}
.price-card.highlight{border:1px solid rgba(255,255,255,0.04);box-shadow:0 8px 30px rgba(139,233,253,0.04)}
.price{font-weight:700;font-size:1.6rem;margin:8px 0}
.price-unit{display:block;color:var(--muted);font-size:0.9rem}
.mood-method .mood-options{display:flex;gap:10px;margin:10px 0}
.mood-btn{padding:8px 12px;border-radius:10px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted);cursor:pointer}
.mood-btn.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#001;font-weight:700}
.method-card{margin-top:12px;padding:12px;border-radius:10px}
.method-actions{margin-top:12px}
.faq details{margin:8px 0;padding:10px;border-radius:8px}
.final-cta .disclaimer{color:var(--muted);font-size:0.85rem;margin-top:12px}
.site-footer{display:flex;justify-content:space-between;align-items:center;padding:12px 22px;margin:18px;border-radius:10px;color:var(--muted)}
@media(max-width:840px){
  .hero-inner{max-width:100%}
  .pricing-grid{grid-template-columns:1fr}
  .benefit-list{flex-direction:column}
  .social-proof .testimonials{flex-direction:column}
  .main-nav{display:none}
}
/* subtle animations */
.price-value{transition:all .45s ease}
"} 
{"path":"assets/js/main.js","content":"// Main interactive behavior: pricing comparator + mood-to-method + small helpers
document.addEventListener('DOMContentLoaded',function(){
  // Year in footer
  var y=document.getElementById('year'); if(y) y.textContent=(new Date()).getFullYear();

  // Pricing comparator
  var toggle=document.getElementById('priceToggle');
  var priceEls=document.querySelectorAll('.price-value');

  function animateValue(el, start, end, duration){
    var startTime=null; var prefix=''; var suffix='';
    if(isNaN(start)) start=0; if(isNaN(end)) end=0;
    if(el.textContent.trim().startsWith('$')) prefix='$';
    function step(timestamp){
      if(!startTime) startTime=timestamp;
      var progress=Math.min((timestamp-startTime)/duration,1);
      var value=Math.round(start + (end-start)*progress);
      el.textContent = (value===0?"--": prefix + value);
      if(progress<1) window.requestAnimationFrame(step);
    }
    window.requestAnimationFrame(step);
  }

  function updatePrices(showPackage){
    priceEls.forEach(function(el){
      var monthly=el.getAttribute('data-monthly');
      var pack=el.getAttribute('data-package');
      var currentText=el.textContent.replace(/[^0-9\-]/g,'');
      var start = parseInt(currentText) || 0;
      var dest = showPackage ? (pack==='--'?0:parseInt(pack)) : (monthly==='--'?0:parseInt(monthly));
      animateValue(el,start,dest,420);
      // adjust unit text nearby
      var unit=el.parentElement.querySelector('.price-unit');
      if(unit){
        if(showPackage) unit.textContent = pack==='--'?'/pack':'/pack';
        else unit.textContent = monthly==='--'?'/session':'/month';
      }
    });
  }

  if(toggle){
    toggle.addEventListener('change',function(){
      updatePrices(toggle.checked);
    });
    // initial set (monthly view)
    updatePrices(false);
  }

  // Mood-to-Method
  var moods={
    overwhelmed: {
      title: 'Small, momentum-building steps',
      desc: 'When things feel like too much, we focus on simple experiments and supportive structure over a few weeks. This reduces decision fatigue and builds a predictable rhythm.',
      cta: 'Start with an intake'
    },
    stuck: {
      title: 'Clarifying stuck points',
      desc: 'If you feel stuck, brief targeted sessions can map patterns and test specific strategies so you can try changes with less uncertainty.',
      cta: 'Book a focused session'
    },
    restless: {
      title: 'Channeling rest into practice',
      desc: 'Restlessness often responds to short accountability and pacing. A cohort that practices weekly can keep energy directed and sustainable.',
      cta: 'Explore the Cohort Lab'
    },
    curious: {
      title: 'A curious, experimental stance',
      desc: 'Curiosity pairs well with brief skill-focused work: plan, try, reflect. We treat therapy like small experiments you can adjust as you go.',
      cta: 'Ask about options'
    }
  };

  var moodBtns=document.querySelectorAll('.mood-btn');
  var methodTitle=document.getElementById('methodTitle');
  var methodDesc=document.getElementById('methodDesc');
  var methodCta=document.getElementById('methodCta');

  moodBtns.forEach(function(btn){
    btn.addEventListener('click',function(){
      moodBtns.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      var key=btn.getAttribute('data-key');
      var data=moods[key];
      if(!data) return;
      // simple morph animation
      if(methodTitle) { methodTitle.style.opacity=0; setTimeout(()=>{ methodTitle.textContent=data.title; methodTitle.style.opacity=1 },220); }
      if(methodDesc) { methodDesc.style.opacity=0; setTimeout(()=>{ methodDesc.textContent=data.desc; methodDesc.style.opacity=1 },220); }
      if(methodCta){ methodCta.textContent=data.cta; methodCta.setAttribute('href', '{{PRIMARY_CTA_URL}}'); }
    });
  });

  // Accessibility: allow keyboard toggles for mood buttons
  moodBtns.forEach(function(btn){btn.setAttribute('tabindex','0');btn.addEventListener('keydown',function(e){if(e.key==='Enter' || e.key===' ') btn.click();});});

});
"} 
